,'_bhc_source_checked_at','2026-11-19');update_post_meta($id,'_bhc_source_evidence',$row['url'].' | مدل، سایز، OLED، پردازنده، HDR، نرخ نوسازی، صدا و قابلیت‌های بازی از صفحه رسمی بررسی شد.');update_post_meta($id,'_bhc_model',$row['model']);update_post_meta($id,'_bhc_brand_latin','Samsung');update_post_meta($id,'_bhc_structured_specs',wp_json_encode($specs,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));update_post_meta($id,'_bhc_highlights',implode("\n",array_slice(array_values($specs),0,9)));update_post_meta($id,'_bhc_faq','آیا محصول موجود است؟ | خیر، ناموجود است.\nآیا مشخصات برای SKU دقیق است؟ | بله.\nآیا قیمت درج شده؟ | خیر.\nآیا گارانتی ایران قطعی است؟ | پس از تأیید نمایندگی مجاز.');update_post_meta($id,'_bhc_warranty','گارانتی و خدمات پس از فروش باید هنگام تأمین تأیید شود.');update_post_meta($id,'_bhc_shipping_note','ارسال و نصب پس از تأیید موجودی، اصالت و نسخه منطقه‌ای انجام می‌شود.');update_post_meta($id,'_bhc_verification_status','needs_editor_review');update_post_meta($id,'_bhc_catalog_quality_state','reference_needs_verification');update_post_meta($id,'_bhc_image_generation_status','awaiting_product_reference');$prompt=function_exists('bhc_catalog_scale_image_prompt')?bhc_catalog_scale_image_prompt($p):'';if($prompt)update_post_meta($id,'_bhc_image_prompt',$prompt);if(function_exists('bhc_catalog_seo_contract'))foreach(bhc_catalog_seo_contract($p) as $key=>$value)if($key!=='source_url')update_post_meta($id,'_bhc_seo_'.$key,$value);$created++;}
